418	  function tryLocateModelTestFolder(searchPattern: string): string {
419	    const folderCandidates: string[] = [];
420	    // 1 - check whether search pattern is a directory
421	    if (fs.existsSync(searchPattern) && fs.lstatSync(searchPattern).isDirectory()) {
422	      folderCandidates.push(searchPattern);
423	    }
424	
425	    // 2 - check the globby result of searchPattern
426	    // 3 - check the globby result of ONNX root combined with searchPattern
427	    const globbyPattern = [
428	      searchPattern,
429	      path.join(TEST_DATA_MODEL_NODE_ROOT, '**', searchPattern).replace(/\\/g, '/'),
430	    ];
431	    // 4 - check the globby result of NODE root combined with opset versions and searchPattern
432	    globbyPattern.push(
433	      ...DEFAULT_OPSET_VERSIONS.map((v) =>
434	        path.join(TEST_DATA_MODEL_NODE_ROOT, `opset${v}`, '**', searchPattern).replace(/\\/g, '/'),
435	      ),
436	    );
437	
438	    folderCandidates.push(...globbySync(globbyPattern, { onlyDirectories: true, absolute: true }));
439	
440	    // pick the first folder that matches the pattern
441	    for (const folderCandidate of folderCandidates) {
442	      const modelCandidates = globbySync('*.{onnx,ort}', { onlyFiles: true, cwd: folderCandidate });
443	      if (modelCandidates && modelCandidates.length === 1) {
444	        return folderCandidate;
445	      }
446	    }
447	
448	    throw new Error(`no model folder found: ${searchPattern}`);
449	  }
