54	void AccumulateTimeSpec(TIME_SPEC* base, const TIME_SPEC* p_y, const TIME_SPEC* p_x) {
55	  TIME_SPEC y_l = *p_y;
56	  TIME_SPEC x_l = *p_x;
57	  TIME_SPEC* y = &y_l;
58	  TIME_SPEC* x = &x_l;
59	  /* Perform the carry for the later subtraction by updating y. */
60	  if (x->tv_nsec < y->tv_nsec) {
61	    long nsec = (y->tv_nsec - x->tv_nsec) / 1000000000 + 1;
62	    y->tv_nsec -= 1000000000 * nsec;
63	    y->tv_sec += nsec;
64	  }
65	  if (x->tv_nsec - y->tv_nsec > 1000000000) {
66	    long nsec = (x->tv_nsec - y->tv_nsec) / 1000000000;
67	    y->tv_nsec += 1000000000 * nsec;
68	    y->tv_sec -= nsec;
69	  }
70	
71	  /* Compute the time remaining to wait.
72	     tv_nsec is certainly positive. */
73	  base->tv_sec += x->tv_sec - y->tv_sec;
74	  base->tv_nsec += x->tv_nsec - y->tv_nsec;
75	  if (base->tv_nsec >= 1000000000) {
76	    base->tv_nsec -= 1000000000;
77	    ++base->tv_sec;
78	  }
79	}
